function crOptions(values,selected,labels=values){return (Array.isArray(values)?values:Object.keys(values)).map(value=>`<option value="${escape(value)}" ${String(selected)===String(value)?'selected':''}>${escape(Array.isArray(labels)?value:labels[value]||value)}</option>`).join('');}
