function crReportPayload(form){
  const values=new FormData(form);let report;
  try{report=JSON.parse(String(values.get('report')||''));}catch{throw new Error('JSON 형식이 올바르지 않아요. 보고서 내용을 확인해 주세요.');}
  if(!report||typeof report!=='object'||Array.isArray(report))throw new Error('조사 보고서는 JSON 객체여야 합니다.');
  const allowed=new Set(['schemaVersion','reportId','date','provider','entries','visibility','shareConfirmed','asOfAt','researchStartedAt','researchCompletedAt']);
  if(Object.keys(report).some(key=>!allowed.has(key)))throw new Error('보고서에 지원하지 않는 항목이 있어요. 정해진 보고서 형식을 사용해 주세요.');
  if(report.schemaVersion!==1||typeof report.reportId!=='string'||!report.reportId.trim()||typeof report.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(report.date)||!['gemini-spark','codex'].includes(report.provider)||!Array.isArray(report.entries)||report.entries.length>30)throw new Error('schemaVersion 1, reportId, 조사 날짜, provider와 자료 30개 이하의 entries가 필요해요.');
  const visibility=values.get('visibility')==='company'?'company':'private';
  const payload={...report,visibility,shareConfirmed:visibility==='company'};if(new TextEncoder().encode(JSON.stringify(payload)).byteLength>1048576)throw new Error('한 보고서는 1MB 이하로 나눠 주세요. 나눈 보고서에는 각각 새 보고서 ID가 필요합니다.');return payload;
}
async function crReadReportFile(input){
  if(!state.user||isViewer())return;crIdentity();const form=input.closest('form'),file=input.files?.[0];if(!form||!file)return;
  const userId=state.user.id,request=++cr.fileRequest,version=state.modalRequest,errorBox=form.querySelector('.form-error'),status=form.querySelector('[data-cr-report-file-status]');errorBox.textContent='';
  try{
    if(!/\.json$/i.test(file.name)||file.size>1048576)throw new Error('1MB 이하의 JSON 파일을 선택해 주세요.');
    const content=await file.text();if(state.user?.id!==userId||request!==cr.fileRequest||state.modalRequest!==version||!form.isConnected)return;
    form.querySelector('[data-cr-report-json]').value=content;if(status)status.textContent=file.name+' 파일을 읽었어요. 공유 범위를 확인한 뒤 저장해 주세요.';
  }catch(error){if(state.user?.id===userId&&request===cr.fileRequest&&state.modalRequest===version&&form.isConnected)errorBox.textContent=error.message;}
}
async function crSaveReport(form){
  if(!state.user||isViewer())return;crIdentity();const submit=form.querySelector('[type="submit"]');if(submit.disabled)return;
  const userId=state.user.id,request=++cr.actionRequest,version=state.modalRequest,errorBox=form.querySelector('.form-error');errorBox.textContent='';submit.disabled=true;
  try{
    const result=await api('/api/creative-research/import-report',crReportPayload(form));if(state.user?.id!==userId||request!==cr.actionRequest)return;
    if(form.isConnected&&state.modalRequest===version)closeModal();await crLoad();if(state.user?.id!==userId||request!==cr.actionRequest)return;
    const report=result.report||{};notify(result.existing?'이미 가져온 조사 보고서예요.':`조사 보고서를 저장했어요. 신규 ${Number(report.createdCount)||0}건 · 갱신 ${Number(report.updatedCount)||0}건`);
  }catch(error){if(state.user?.id===userId&&request===cr.actionRequest){if(form.isConnected&&state.modalRequest===version)errorBox.textContent=error.message;else notify(error.message);}}
  finally{if(submit.isConnected)submit.disabled=false;}
}
